<template>
  <div class="app-container resource-detail-page"><main class="detail-shell"><el-button link class="back-button" @click="back"><el-icon><ArrowLeft /></el-icon>返回搜索结果</el-button><el-empty v-if="!resource && !loading" description="暂无详情抓取记录" /><template v-else-if="resource"><section v-loading="loading" class="summary-card"><div class="detail-icon"><el-icon><FolderOpened v-if="resource.isdir" /><Document v-else /></el-icon></div><div class="summary-main"><h1>{{ resource.filename }}</h1><div class="metadata"><el-tag size="small" effect="plain">百度网盘</el-tag><span>{{ formatSize(resource.size) }}</span><span>{{ resource.updatetime }}</span><el-tag size="small" :type="resource.valid === 1 ? 'success' : 'info'">{{ resource.valid === 1 ? '资源有效' : '资源状态未知' }}</el-tag></div></div><div class="summary-actions"><el-button v-if="resource.haspwd" @click="copyPwd"><el-icon><CopyDocument /></el-icon>复制提取码</el-button><el-button type="primary" :disabled="!resource.url" @click="openShare"><el-icon><Link /></el-icon>前往网盘</el-button></div></section><section class="detail-card"><div class="section-heading"><div><h2>目录内容</h2><p>展示本次抓取的详情目录</p></div><span>{{ resource.filelist.length }} 个条目</span></div><ul class="detail-files"><li v-for="file in resource.filelist" :key="file.filename"><el-icon :class="{ folder: file.isdir }"><FolderOpened v-if="file.isdir" /><Document v-else /></el-icon><span>{{ file.filename }}</span><em v-if="file.size">{{ formatSize(file.size) }}</em></li></ul></section><section v-if="resource.similar_shares?.length" class="detail-card"><div class="section-heading"><div><h2>其他相似分享</h2><p>名称相同且目录高度相似的资源</p></div><span>{{ resource.similar_shares.length }} 个</span></div><ul class="detail-files"><li v-for="share in resource.similar_shares" :key="share.id"><span>{{ share.filename }}</span><em>目录相似 {{ Math.round((share.file_similarity || 0) * 100) }}%</em><el-button link type="primary" :disabled="!share.url" @click.stop="openShareUrl(share.url)">前往网盘</el-button></li></ul></section></template></main></div>
</template>

<script setup name="FeizhuResourceDetail">
import { onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowLeft, CopyDocument, Document, FolderOpened, Link } from '@element-plus/icons-vue'
import { getResourceDetail } from '@/api/feizhu/resource'

const route = useRoute(), router = useRouter()
const resource = ref(null), loading = ref(false)
async function load() { const id = typeof route.query.id === 'string' ? route.query.id : ''; if (!id) return; loading.value = true; try { resource.value = await getResourceDetail(id) } catch { resource.value = null } finally { loading.value = false } }
function formatSize(value) { const size = Number(value); if (!Number.isFinite(size) || size <= 0) return '--'; const units = ['B', 'KB', 'MB', 'GB', 'TB']; const index = Math.min(Math.floor(Math.log(size) / Math.log(1024)), units.length - 1); return `${Math.floor(size / 1024 ** index)}${units[index]}` }
function back() { router.push({ path: '/feizhu/resource-search', query: { kw: route.query.kw || undefined } }) }
async function copyPwd() { await navigator.clipboard.writeText(resource.value.pwd); ElMessage.success('提取码已复制') }
function openShare() { window.open(resource.value.url, '_blank', 'noopener,noreferrer') }
function openShareUrl(url) { window.open(url, '_blank', 'noopener,noreferrer') }
onMounted(load)
watch(() => route.query.id, load)
</script>

<style scoped lang="scss">
.resource-detail-page { min-height:100%; background:#f6f7fb; }.detail-shell { max-width:1040px; margin:0 auto; padding:24px 16px 44px; }.back-button { margin-bottom:14px; }.summary-card,.detail-card { display:flex; gap:18px; padding:24px; border:1px solid #ebeef5; border-radius:10px; background:#fff; box-shadow:0 3px 12px rgba(0,0,0,.03); }.detail-icon { display:grid; flex:none; place-items:center; width:56px; height:56px; border-radius:9px; color:#d99723; background:#fff7e7; font-size:29px; }.summary-main { min-width:0; flex:1; }.summary-main h1 { margin:1px 0 10px; overflow:hidden; color:#303133; font-size:20px; text-overflow:ellipsis; white-space:nowrap; }.metadata { display:flex; flex-wrap:wrap; align-items:center; gap:9px; color:#8a919f; font-size:13px; }.summary-actions { display:flex; align-self:center; flex:none; gap:10px; }.summary-actions .el-icon { margin-right:4px; }.detail-card { display:block; margin-top:16px; }.section-heading { display:flex; justify-content:space-between; align-items:center; padding-bottom:16px; border-bottom:1px solid #eef0f4; }.section-heading h2 { margin:0; color:#303133; font-size:16px; }.section-heading p { margin:6px 0 0; color:#909399; font-size:13px; }.section-heading > span { color:#909399; font-size:13px; }.detail-files { margin:0; padding:0; list-style:none; }.detail-files li { display:flex; align-items:center; gap:10px; min-height:50px; border-bottom:1px solid #f1f2f4; color:#4e5969; font-size:14px; }.detail-files li:last-child { border-bottom:0; }.detail-files .el-icon { color:var(--el-color-primary); font-size:17px; }.detail-files .el-icon.folder { color:#d99723; }.detail-files li span { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }.detail-files em { margin-left:auto; color:#969ba5; font-style:normal; white-space:nowrap; }.notice { margin:16px 2px 0; color:#909399; font-size:12px; text-align:center; }
@media (max-width:768px) { .detail-shell { padding:18px 10px 28px; }.summary-card { align-items:flex-start; flex-wrap:wrap; padding:18px; gap:12px; }.detail-icon { width:42px; height:42px; font-size:23px; }.summary-main { width:calc(100% - 54px); flex:none; }.summary-main h1 { font-size:17px; }.summary-actions { width:100%; }.detail-card { padding:18px; }.detail-files li { min-height:46px; }.detail-files em { font-size:12px; } }
</style>
